def get_header_dict(value):
    """function to convert string header to dictionary"""
    values = value.rstrip("\n").split("\n")
    header_dict = {}
    for value in values:
        key, value = value.split(":", 1)
        header_dict[key.rstrip().lstrip()] = value.lstrip().rstrip()

    return header_dict

